  `token_expires_at` timestamp NULL DEFAULT NULL,
  `password_reset_token` varchar(255) DEFAULT NULL,
  `reset_token_expires_at` timestamp NULL DEFAULT NULL,
  `alert_preferences` json DEFAULT (_utf8mb4'{}'),
  `monitor_live_location` tinyint(1) DEFAULT '0',
  `notification_preferences` json DEFAULT (_utf8mb4'{"email": true, "sms": false}'),
  `sms_carrier` varchar(50) DEFAULT NULL,
  `sms_enabled` tinyint(1) DEFAULT '0',
  `phone_number` varchar(20) DEFAULT NULL,
  `is_active` tinyint(1) DEFAULT '1',
  `browser_notifications_enabled` tinyint(1) DEFAULT '0',
  `is_logged_in` tinyint(1) NOT NULL DEFAULT '0',
  `last_activity_at` datetime DEFAULT NULL,
  `location_tracking_enabled` tinyint(1) DEFAULT '0',
  `location_update_interval` int DEFAULT '30',
  `background_location_tracking` tinyint(1) DEFAULT '1',
  `high_risk_alerts_only` tinyint(1) DEFAULT '0',
  `last_location_update` timestamp NULL DEFAULT NULL,
  `location_source` varchar(20) DEFAULT 'gps',
  `google_id` varchar(255) DEFAULT NULL,
  `email_verified` tinyint(1) DEFAULT '0',
  `otp_code` varchar(10) DEFAULT NULL,
  `otp_expires_at` timestamp NULL DEFAULT NULL,
  `password_must_change` tinyint(1) DEFAULT '0',
  `email_alerts_enabled` tinyint(1) DEFAULT '1',
  `weekly_reports_enabled` tinyint(1) DEFAULT '1',
  `incident_alerts_enabled` tinyint(1) DEFAULT '1',
  `live_alerts_enabled` tinyint(1) DEFAULT '1',
  PRIMARY KEY (`id`),
  UNIQUE KEY `username` (`username`),
  UNIQUE KEY `email` (`email`),
  UNIQUE KEY `google_id` (`google_id`),
  KEY `idx_email_verification_token` (`email_verification_token`),
  KEY `idx_token_expires_at` (`token_expires_at`),
  KEY `idx_password_reset_token` (`password_reset_token`),
  KEY `idx_reset_token_expires` (`reset_token_expires_at`),
  KEY `idx_google_id` (`google_id`)
) ENGINE=InnoDB AUTO_INCREMENT=49 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

